urlset:
{%- for file in pages %}
  {%- if not file.page.is_link and file.page.canonical_url %}

    {{ file.page.canonical_url|e }}
    {% if file.page.update_date %}{{ file.page.update_date }}{% endif %}

  {# Both public mounts serve this snapshot. Material only retains navigation for sitemap URLs. #}
  {%- for base in config.extra.sitemap_aliases %}

    {{ (base ~ ('' if file.url == './' else file.url))|e }}
    {% if file.page.update_date %}{{ file.page.update_date }}{% endif %}

  {%- endfor %}
  {%- endif %}
{%- endfor %}
